    >>> graph = ...
    >>> ymax  = graph.ymax ()
    """
def _gr_ymax_(graph: Any) -> object {
    ymx = None;
    np = len(graph);
    for ip in range(np) {
        (x, y) = graph[ip];
        if ((None == ymx) or (y >= ymx)) {
            ymx = y;
        }
    }
    return ymx;
}

